# AMD ROCm blog on reproducing the MLPerf Inference v6.1 submission, held against the v6.1 result file and summary spreadsheet. python3 -I check_claims_amd_repro_v61.py
import json,hashlib,re
FILES=['raw/inf_6.1.json','raw/v61_ids.json','raw/older_rounds_systems.json','raw/inf_5.0.json','raw/inf_5.1.json','raw/inf_6.0.json']; RAW={f:open(f,'rb').read() for f in FILES}
B=list(json.loads(RAW[FILES[0]]).values()); D=json.loads(RAW[FILES[1]]); OLD=json.loads(RAW[FILES[2]]); V5=json.loads(RAW[FILES[3]]); V51=json.loads(RAW[FILES[4]]); V0=json.loads(RAW[FILES[5]]); s=str; pc=lambda x,y:100*(x/y-1)
import re as _re
_KEEP={'bert','rgat','retinanet','resnet','dlrm','unet','sdxl'}
def _and(L): return L[0] if len(L)==1 else ', '.join(L[:-1])+' and '+L[-1]
def _pl(s,prose=False):   # a table cell as plain text: no semicolons, and in the data cells no Python list, True/False or None
    if not isinstance(s,str): return s
    if not prose:
        s=_re.sub(r"\[((?:'[^']*'(?:, )?)+)\]",lambda m:_and(_re.findall(r"'([^']*)'",m.group(1))),s).replace('[]','none')
        s=_re.sub(r'\bTrue\b','yes',s); s=_re.sub(r'\bFalse\b','no',s); s=_re.sub(r'\bNone\b','none',s)
    return _re.sub(r'; ([a-z]+)\b(?![-_./])',lambda m:'. '+(m.group(1) if m.group(1) in _KEEP else m.group(1).capitalize()),s).replace('; ','. ')
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=_pl(calc),stated=_pl(st),delivered=_pl(got),outcome=out,note=_pl(note,True),label_mismatch=False)
def dv(i,m,sc): return D[i]['results'].get(f'{m}|{sc}')
RP=[]
# expected results table
partners8=lambda m,sc:[x['Result'] for x in B if x['Division']=='closed' and x['Model']==m and x['Scenario']==sc and x['total_accelerators']==8 and 'MI355X' in s(x['accelerator_model_name']) and x['Organization']!='AMD']
E=[('dlrm-v3','MI355X','Offline',13000,('6.1-0003','dlrm-v3','Offline')),('dlrm-v3','MI355X','Server',12000,('6.1-0003','dlrm-v3','Server')),('dlrm-v3','MI350X','Offline',10500,('6.1-0001','dlrm-v3','Offline')),('dlrm-v3','MI350X','Server',9200,('6.1-0001','dlrm-v3','Server')),('dlrm-v3','MI350P','Offline',4500,('6.1-0040','dlrm-v3','Offline')),('dlrm-v3','MI350P','Server',4200,('6.1-0040','dlrm-v3','Server')),
('gpt-oss-120b','MI355X','Offline',120000,('6.1-0003','gpt-oss-120b','Offline')),('gpt-oss-120b','MI355X','Server',111000,('6.1-0003','gpt-oss-120b','Server')),('gpt-oss-120b','MI350P','Offline',48000,('6.1-0040','gpt-oss-120b','Offline')),('gpt-oss-120b','MI350P','Server',40000,('6.1-0040','gpt-oss-120b','Server')),('gpt-oss-120b 72 GPUs','MI355X','Offline',1000900,('6.1-0004','gpt-oss-120b','Offline')),('gpt-oss-120b 72 GPUs','MI355X','Server',950468,('6.1-0004','gpt-oss-120b','Server')),
('llama2-70b','MI355X','Interactive',72000,('6.1-0003','llama2-70b-99.9','Interactive')),('llama2-70b','MI355X','Offline',105000,('6.1-0003','llama2-70b-99.9','Offline')),('llama2-70b','MI355X','Server',101000,('6.1-0003','llama2-70b-99.9','Server')),('llama2-70b','MI350P','Interactive',21000,('6.1-0040','llama2-70b-99.9','Interactive')),('llama2-70b','MI350P','Offline',41000,('6.1-0040','llama2-70b-99.9','Offline')),('llama2-70b','MI350P','Server',40000,('6.1-0040','llama2-70b-99.9','Server')),
('wan2.2-t2v','MI355X','Offline',0.07,('6.1-0003','text_to_video','Offline')),('wan2.2-t2v','MI355X','Single Stream',16.0,('6.1-0003','text_to_video','SingleStream')),('wan2.2-t2v','MI350X','Offline',0.05,('6.1-0002','text_to_video','Offline')),('wan2.2-t2v','MI350X','Single Stream',20.0,('6.1-0002','text_to_video','SingleStream')),('wan2.2-t2v','MI350P','Offline',0.035,('6.1-0040','text_to_video','Offline')),('wan2.2-t2v','MI350P','Single Stream',41.0,('6.1-0040','text_to_video','SingleStream'))]
rows=[(m,p,sc,e,dv(*k),pc(dv(*k),e)) for m,p,sc,e,k in E]; off=[r for r in rows if abs(r[5])>3]
RP.append(mk('RP1','Expected Results table in the post, AMD entries','v6.1 summary spreadsheet, AMD and Dell and AMD entries (6.1-0001 to 6.1-0004 and 6.1-0040), same model, platform and scenario','expected values within 3% of a run, which the post gives as the usual variation',f'{len(rows)-len(off)} of {len(rows)} file values are within 3% of the expected value; outside 3%: '+'; '.join(f'{m} {p} {sc} expected {e:,.10g}, file {f:,.10g} ({d:+.1f}%)' for m,p,sc,e,f,d in off),'CONSISTENT' if not off else 'BELOW','The 72-GPU rows are labelled as such in the post. The post does not say the expected values are targets for the submitted runs. Our rule: the 3% in the post is the tolerance.'))
ll=lambda sc:partners8('llama3.1-8b',sc)
exp=[('Offline',165000),('Server',155000),('Interactive',140000)]
RP.append(mk('RP2','Expected Results rows for llama3.1-8b on MI355X','eight-GPU MI355X Llama 3.1 8B entries from partners in the v6.1 file; AMD has no Llama 3.1 8B MI355X entry','~165,000, ~155,000 and ~140,000 tokens/s','; '.join(f'{sc} expected {e:,}: partner range {min(ll(sc)):,.0f} to {max(ll(sc)):,.0f}' for sc,e in exp),'CONSISTENT' if all(min(ll(sc))*0.97<=e<=max(ll(sc))*1.03 for sc,e in exp) else 'BELOW','AMD itself has no Llama 3.1 8B entry on the MI355X. The expected values are compared with the five partner entries.'))
RP.append(mk('RP3','Expected Results rows for deepseek-r1 on MI355X','AMD and Dell and AMD DeepSeek-R1 entries in the v6.1 file','~51,000 and ~41,000 tokens/s on MI355X',f'AMD-labelled DeepSeek-R1 entries: {sum(1 for x in B if x["Model"]=="deepseek-r1" and x["Organization"] in ("AMD","Dell_AMD"))}; the only AMD Instinct DeepSeek-R1 entry is Crusoe on 512 MI355X, Offline {dv("6.1-0026","deepseek-r1","Offline"):,.0f}','CANNOT_TELL','There is no eight-GPU MI355X DeepSeek-R1 entry in the file to compare with.'))
amd=[x for x in B if x['Organization'] in('AMD','Dell_AMD')]
have={}
for x in amd: have.setdefault(x['Model'],set()).add(re.search(r'MI3\d\d[XP]',s(x['accelerator_model_name'])).group())
RP.append(mk('RP4','Workloads summary table in the post','models and platforms of AMD and Dell and AMD entries in the v6.1 file','six models with the platforms listed',', '.join(f'{m}: {sorted(v)}' for m,v in sorted(have.items())),'BELOW','DeepSeek-R1 has no AMD-labelled entry. Llama 3.1 8B appears for the MI350P and not for the MI355X. The post lists the opposite for both.'))
RP.append(mk('RP5','Completed samples per second : 12198.83','AMD eight-GPU MI355X DLRM-v3 Server, closed division','12198.83 completed samples per second',f'{dv("6.1-0003","dlrm-v3","Server"):,.2f} queries/s','CONSISTENT' if abs(dv('6.1-0003','dlrm-v3','Server')-12198.83)<0.05 else 'BELOW','The post prints the sample run output. The 99th percentile latency of 60.43 ms is not a file field.'))
rd=[r[1:] for r,v in OLD.items() if 'AMD' in v['submitters']]+[n for L,n in((V5,'5.0'),(V51,'5.1'),(V0,'6.0')) if any(x['Submitter']=='AMD' for x in L)]+['6.1']
RP.append(mk('RP6','AMD MLPerf Inference v6.1 submission is our fifth consecutive round of MLPerf Inference participation.','rounds with an AMD submission in the v3.1 to v6.1 sources','fifth consecutive round',f'AMD appears in {sorted(rd)}','CONSISTENT' if len(rd)==5 else 'BELOW','Rounds v3.1 and v4.0 were read from system description files with a cut-short list, where AMD would sort first.'))
rocm=sorted({m.group() for x in amd for m in re.finditer(r'ROCm \d+\.\d+(\.\d+)?|rocm\d+\.\d+(\.\d+)?',s(x['framework'])+' '+s(x['notes'])+' '+s(x.get('operating_system')))})
sw=sorted({s(v['results'] and '') for v in []})
RP.append(mk('RP7','ROCm: [PLACEHOLDER: ROCm version, e.g., ROCm 6.4]','software fields of the AMD entries in the v6.1 file','a ROCm version for the prerequisites',f'framework and notes fields of AMD-labelled entries name: {rocm}','CANNOT_TELL','The published page carries the placeholder text in place of a version. The file names the versions used in the submitted runs.'))
RP.append(mk('RP8','Total disk space required across all workloads is approximately 5GB. ... Note that dlrm-v3 dominates the total at roughly 1.2 TB on its own, and also requires about 3 TB of host system memory.','arithmetic on the two figures in the post','5GB in total and 1.2 TB for one workload','1.2 TB is about 240 times 5GB','CANNOT_TELL','The two figures in the post cannot both be the total. Neither is a result file field.'))
json.dump(dict(source=FILES,sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES],claims=RP),open('claims_amd_repro_v61.json','w'),indent=1)
for c in RP: print(c['id'],c['outcome'],'|',c['stated'][:44],'|',c['delivered'][:420])
